# Let's look at the tool calls around the changes to dictutils and setutils
# Search for "write" or "edit" operations
for term in ["write", "edit", "file_write", "file_edit"]:
    r = await CONTEXT.search(term)
    if isinstance(r, dict) and 'items' in r:
        print(f"\n{term}: {len(r['items'])} matches")
        for item in r['items'][:5]:
            print(f"  offset={item['offset']}, snippet={item['snippet'][:200]}")
    else:
        print(f"\n{term}: {r}")
